[InitializeOnLoad]
public static class AircraftMetalPolish
{
 const string Dir="Assets/Materials/FinalRanking/";
 static readonly float[] X={-9,-8,-6,-3,1,4,5.7f,7,7.8f,8.25f},R={.2f,.6f,1.22f,1.35f,1.35f,1.3f,1.1f,.75f,.35f,.04f};
 static AircraftMetalPolish(){EditorApplication.update+=Poll;}
 static void Poll(){if(!System.IO.File.Exists("Library/AircraftMetal.request")||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;System.IO.File.Delete("Library/AircraftMetal.request");try{Build();System.IO.File.WriteAllText("Library/AircraftMetal.result","PASS: closed thick aircraft shells, separate inner metal, curled torn rim, smooth shared normals, localized soot, retained paint and metal/smoothness detail.");}catch(Exception e){Debug.LogException(e);System.IO.File.WriteAllText("Library/AircraftMetal.result","FAIL: "+e);}}
 static float Radius(float x){for(int i=1;i<X.Length;i++)if(x<=X[i])return Mathf.Lerp(R[i-1],R[i],Mathf.InverseLerp(X[i-1],X[i],x));return R[R.Length-1];}
 static Texture2D Texture(string name,int w,int h){string path=Dir+name+".asset";var t=AssetDatabase.LoadAssetAtPath<Texture2D>(path);if(t==null){t=new Texture2D(w,h,TextureFormat.RGBA32,true){name=name,wrapMode=TextureWrapMode.Repeat,filterMode=FilterMode.Trilinear};AssetDatabase.CreateAsset(t,path);}return t;}
 static Material Material(string n,Color c,float metal,float gloss){string path=Dir+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null){m=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(m,path);}m.color=c;m.SetFloat("_Metallic",metal);m.SetFloat("_Glossiness",gloss);return m;}
 static Material Paint(){const int w=1024,h=512;var color=Texture("Patchy aircraft paint and localized soot",w,h);var spec=Texture("Aircraft exposed metal and rough char",w,h);var bump=Texture("Aircraft fine pitted metal normals",w,h);var a=new Color[w*h];var s=new Color[w*h];var b=new Color[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){float u=x/(float)(w-1),v=y/(float)(h-1),angle=v*Mathf.PI*2;float noise=Mathf.PerlinNoise(x*.019f,y*.026f),grain=Mathf.PerlinNoise(x*.35f,y*.35f);float hole=Mathf.Exp(-Mathf.Pow((u-.477f)/.135f,2));float burn=Mathf.Clamp01(hole*(.65f+noise*.7f)+Mathf.Max(0,noise-.64f)*.7f);float peel=Mathf.SmoothStep(.44f,.64f,noise)*hole;Color intact=Mathf.Sin(angle)<-.2f?new Color(.10f,.29f,.34f):new Color(.79f,.77f,.69f);Color bare=new Color(.47f,.51f,.52f);Color baseColor=Color.Lerp(intact,bare,peel*.7f);Color charColor=Color.Lerp(new Color(.065f,.075f,.08f),new Color(.22f,.16f,.11f),noise);a[y*w+x]=Color.Lerp(baseColor,charColor,burn*.88f)*( .91f+grain*.12f);s[y*w+x]=new Color(Mathf.Lerp(.16f,.72f,peel)*(1-burn*.65f),0,0,Mathf.Lerp(.5f,.16f,burn));float dx=(Mathf.PerlinNoise((x+1)*.23f,y*.23f)-Mathf.PerlinNoise((x-1)*.23f,y*.23f))*.13f;float dy=(Mathf.PerlinNoise(x*.23f,(y+1)*.23f)-Mathf.PerlinNoise(x*.23f,(y-1)*.23f))*.13f;b[y*w+x]=new Color(1,.5f+dy,.5f,.5f+dx);}
 color.SetPixels(a);color.Apply();spec.SetPixels(s);spec.Apply();bump.SetPixels(b);bump.Apply();EditorUtility.SetDirty(color);EditorUtility.SetDirty(spec);EditorUtility.SetDirty(bump);var material=Material("Layered scorched airliner paint",Color.white,.4f,.45f);material.mainTexture=color;material.SetTexture("_MetallicGlossMap",spec);material.EnableKeyword("_METALLICGLOSSMAP");material.SetTexture("_BumpMap",bump);material.SetFloat("_BumpScale",.28f);material.EnableKeyword("_NORMALMAP");return material;}
 static void Quad(List<int> list,int a,int b,int c,int d){list.AddRange(new[]{a,b,c,a,c,d});}
 static void Shell(Transform parent,string name,float min,float max,bool tornAtMax,Material outer,Material inner)
 {
  var prior=parent.Find(name);if(prior!=null)Object.DestroyImmediate(prior.gameObject);
  const int rings=48,around=96;var vertices=new List<Vector3>();var uv=new List<Vector2>();var outside=new List<int>();var inside=new List<int>();var rim=new List<int>();
  for(int layer=0;layer<2;layer++)for(int i=0;i<=rings;i++)for(int j=0;j<=around;j++){float t=i/(float)rings,angle=j*Mathf.PI*2/around;float nominal=Mathf.Lerp(min,max,t);float edge=tornAtMax?Mathf.Pow(t,9):Mathf.Pow(1-t,9);float jagged=(Mathf.Sin(angle*7+.4f)*.16f+Mathf.Sin(angle*13)*.055f)*edge;float x=nominal+jagged;float r=Radius(nominal);float dents=(Mathf.PerlinNoise(nominal*.8f+20,Mathf.Cos(angle)*2+Mathf.Sin(angle)*3+20)-.5f)*.07f;float flare=edge*(.04f+Mathf.Sin(angle*5)*.045f);r=Mathf.Max(.025f,r+dents+flare-(layer==1?.075f:0));vertices.Add(new Vector3(x,Mathf.Sin(angle)*r,Mathf.Cos(angle)*r));uv.Add(new Vector2(Mathf.InverseLerp(-9,8.25f,nominal),j/(float)around));}
  int stride=around+1,offset=(rings+1)*stride;for(int i=0;i<rings;i++)for(int j=0;j<around;j++){int a=i*stride+j,b=a+stride;Quad(outside,a,b,b+1,a+1);Quad(inside,a+offset,a+1+offset,b+1+offset,b+offset);}for(int j=0;j<around;j++){Quad(rim,j,j+1,j+1+offset,j+offset);int a=rings*stride+j;Quad(rim,a+1,a,a+offset,a+1+offset);}
  string path="Assets/Prefabs/FinalRanking/"+name+".asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){mesh=new Mesh();AssetDatabase.CreateAsset(mesh,path);}mesh.Clear();mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.subMeshCount=3;mesh.SetTriangles(outside,0);mesh.SetTriangles(inside,1);mesh.SetTriangles(rim,2);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);var g=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(parent,false);g.GetComponent<MeshFilter>().sharedMesh=mesh;g.GetComponent<MeshRenderer>().sharedMaterials=new[]{outer,inner,inner};
 }
 static void Tube(Transform parent,string name,Vector3 a,Vector3 b,float radius,Material material){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=(a+b)*.5f;g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);g.transform.localScale=new Vector3(radius*2,(b-a).magnitude*.5f,radius*2);Object.DestroyImmediate(g.GetComponent<Collider>());g.GetComponent<Renderer>().sharedMaterial=material;}
 static void CombineDetails(Transform root)
 {
  var filters=root.GetComponentsInChildren<MeshFilter>();var materials=filters.Select(f=>f.GetComponent<Renderer>().sharedMaterial).Distinct().ToArray();
  foreach(var material in materials){var instances=filters.Where(f=>f.GetComponent<Renderer>().sharedMaterial==material).Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=root.worldToLocalMatrix*f.transform.localToWorldMatrix}).ToArray();string name=root.parent.name+" "+material.name+" construction";string path="Assets/Prefabs/FinalRanking/"+name+".asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){mesh=new Mesh();AssetDatabase.CreateAsset(mesh,path);}mesh.Clear();mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.CombineMeshes(instances,true,true);EditorUtility.SetDirty(mesh);var g=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(root,false);g.GetComponent<MeshFilter>().sharedMesh=mesh;g.GetComponent<MeshRenderer>().sharedMaterial=material;}
  foreach(var filter in filters)Object.DestroyImmediate(filter.gameObject);
 }
 public static void Build(){if(!EditorSceneManager.SaveOpenScenes())throw new Exception("Save failed");var setup=EditorSceneManager.GetSceneManagerSetup();EditorSceneManager.OpenScene("Assets/Scenes/FinalRanking.unity");var plane=GameObject.Find("PARTY AIR · detailed damaged passenger jet").transform;var paint=Paint();var inner=Material("Oxidized inner aluminium",new Color(.32f,.35f,.36f),.72f,.36f);var rivet=Material("Exposed brushed aluminium fasteners",new Color(.62f,.65f,.64f),.85f,.56f);
  foreach(var section in new[]{"Torn aft fuselage","Separated cockpit wreck"}){var parent=plane.Find(section);bool aft=section.StartsWith("Torn");var old=parent.Find(aft?"Jagged aft fuselage shell":"Jagged forward fuselage shell");if(old!=null)Object.DestroyImmediate(old.gameObject);Shell(parent,aft?"Thick torn aft aluminium skin":"Thick torn forward aluminium skin",aft?-9:.9f,aft?-2.1f:8.25f,aft,paint,inner);var details=parent.Find("Metal construction details");if(details!=null)Object.DestroyImmediate(details.gameObject);details=new GameObject("Metal construction details").transform;details.SetParent(parent,false);float min=aft?-7.6f:1.3f,max=aft?-2.3f:6.7f;
   for(float x=min;x<max;x+=.73f){float r=Radius(x)+.018f;for(int j=0;j<32;j++){float angle=j*Mathf.PI/16,next=(j+1)*Mathf.PI/16;Tube(details,"Recessed panel circumferential seam",new Vector3(x,Mathf.Sin(angle)*r,Mathf.Cos(angle)*r),new Vector3(x,Mathf.Sin(next)*r,Mathf.Cos(next)*r),.008f,inner);}for(int j=0;j<6;j++){float angle=.42f+j*Mathf.PI/3;Vector3 at=new Vector3(x,Mathf.Sin(angle)*(r+.012f),Mathf.Cos(angle)*(r+.012f));var bolt=GameObject.CreatePrimitive(PrimitiveType.Sphere);bolt.name="Flush rivet head";bolt.transform.SetParent(details,false);bolt.transform.localPosition=at;bolt.transform.localScale=Vector3.one*.035f;Object.DestroyImmediate(bolt.GetComponent<Collider>());bolt.GetComponent<Renderer>().sharedMaterial=rivet;}}
   float cut=aft?-2.1f:.9f;for(int i=0;i<12;i++){float angle=i*Mathf.PI/6;Vector3 from=new Vector3(cut,Mathf.Sin(angle)*1.19f,Mathf.Cos(angle)*1.19f);Vector3 mid=from+Vector3.right*(aft?.16f:-.16f)+new Vector3(0,Mathf.Sin(angle)*.04f,Mathf.Cos(angle)*.04f);Vector3 tip=mid+Vector3.right*(aft?.13f:-.13f)+new Vector3(0,Mathf.Sin(angle)*.13f,Mathf.Cos(angle)*.13f);Tube(details,"Curled bare metal tear lip",from,mid,.026f,rivet);Tube(details,"Turned torn metal edge",mid,tip,.023f,rivet);}
   CombineDetails(details);
  }
  // Smaller debris still shares the painted/charred metal instead of a uniformly black surface.
  foreach(var renderer in plane.parent.GetComponentsInChildren<Renderer>())if(renderer.name.StartsWith("Scattered aircraft skin panel")||renderer.name.StartsWith("Torn curled skin edge"))renderer.sharedMaterial=paint;
  EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();EditorSceneManager.RestoreSceneManagerSetup(setup);
 }
}
